from produire import produire
from format_lecon import paras,table,steps
from medicaments import nasonex
parts=[
('La {polypose nasosinusienne est une forme inflammatoire de rhinosinusite chronique}. Les polypes sont des excroissances muqueuses bénignes. Ils peuvent obstruer le nez et contribuer au ronflement.',paras('Le tableau habituel associe obstruction et diminution de l’odorat, souvent des deux côtés. Une formation unilatérale ne doit pas être étiquetée automatiquement comme une polypose diffuse banale.', 'La maladie nasale peut coexister avec des apnées pharyngées. La réduction des polypes ne permet pas de déduire seule la normalisation du sommeil.')),
('Le {contexte est chronique et parfois associé à un asthme}. Les symptômes ont un retentissement sur sommeil et qualité de vie. Une intolérance respiratoire aux anti-inflammatoires doit être recherchée.',paras('Les HUG décrivent la rhinosinusite chronique comme une inflammation durant au moins trois mois. La polypose est un de ses phénotypes, pas un synonyme de toute sinusite.', 'Les mécanismes inflammatoires varient. Les formes persistantes ou récidivantes nécessitent une appréciation ORL de la gravité et des maladies associées, plutôt qu’une succession de traitements courts non évalués.')),
('L’{œdème inflammatoire réduit le passage de l’air et l’accès olfactif}. Les polypes occupent les cavités nasales et sinusiennes. Leur développement est différent de celui d’une tumeur maligne.',paras('Une inflammation de type 2 peut être impliquée dans certaines formes diffuses et explique des associations avec asthme et récidive. Toutes les rhinosinusites n’ont pas le même profil biologique.', 'L’obstruction favorise la respiration buccale. Des troubles du sommeil peuvent résulter de cette gêne ou d’une maladie respiratoire associée ; il faut distinguer ces mécanismes.')),
('Les {alarmes sont surtout l’unilatéralité atypique et les complications}. Saignement, ulcération ou masse irrégulière demandent un examen approfondi. Un trouble visuel ou neurologique impose une évaluation urgente.',paras('La notice suisse de mométasone insiste sur l’exploration des polypes unilatéraux inhabituels, ulcérés ou sanglants. Une réponse partielle à un corticoïde n’exclut pas une autre lésion.', 'Douleur intense, fièvre et signes orbitaires orientent vers une complication infectieuse. Les pauses respiratoires ou une somnolence dangereuse ne doivent pas être attribuées d’emblée au nez bouché.')),
('L’{anamnèse recherche durée, odorat et maladies associées}. Demander obstruction, écoulement, douleurs et traitements antérieurs. Préciser asthme, réactions aux anti-inflammatoires et chirurgie.',paras('Évaluer retentissement sur sommeil, alimentation, activités et travail. Noter durée des améliorations après traitements et régularité des soins locaux.', 'Rechercher signes d’apnées, alcool et médicaments. La perte d’odorat n’est pas spécifique de la polypose ; son apparition et son contexte doivent être précisés.')),
('L’{examen ORL caractérise les formations et la muqueuse}. La rhinoscopie est complétée par une endoscopie selon le cas. L’examen recherche asymétrie et signes suspects.',paras('Documenter obstruction, sécrétions, état des cavités et extension visible. L’endoscopie distingue mieux une formation polypoïde d’une simple tuméfaction des cornets.', 'Évaluer l’asthme et les autres niveaux d’obstruction nocturne selon les symptômes. Un examen nasal ne remplace pas l’étude du sommeil quand elle est indiquée.')),
('L’{approche syndromique différencie plusieurs obstacles nasaux}. Le tableau bilatéral chronique est évocateur mais non suffisant. Les formes localisées demandent une attention particulière.',table(['Présentation','Orientation'],[['Obstruction bilatérale, odorat diminué, polypes visibles.','Polypose inflammatoire probable.'],['Prurit, éternuements, exposition.','Rhinite allergique associée ou alternative.'],['Obstacle fixe sans formation polypoïde.','Déviation ou autre anomalie anatomique.'],['Masse unilatérale irrégulière et sang.','Exclure une tumeur et organiser le bilan.'] ])),
('Le {diagnostic combine symptômes chroniques et constat ORL}. La présence de polypes définit le phénotype. La gravité dépend du contrôle clinique et du retentissement.',paras('Les HUG et EPOS distinguent rhinosinusite chronique avec et sans polypes. L’imagerie seule ne suffit pas à attribuer tous les symptômes à une maladie sinusienne.', 'Une lésion atypique peut nécessiter un prélèvement spécialisé. Une indication de traitement biologique n’est pas déduite de la simple existence d’un polype : elle relève d’une sélection actualisée.')),
('Les {examens précisent extension et contexte}. Un scanner est utile selon le bilan ORL et le projet chirurgical. Des tests supplémentaires répondent à une suspicion clinique.',paras('Une exploration allergologique ou respiratoire peut être pertinente selon les signes. Les marqueurs inflammatoires servent notamment à certaines décisions spécialisées ; ils ne remplacent pas l’examen.', 'Une présentation unilatérale ou suspecte appelle une stratégie d’imagerie et de prélèvement adaptée. Une étude du sommeil reste indiquée si le tableau évoque des apnées.')),
('L’{algorithme combine traitement local et réévaluation}. Vérifier d’abord les alarmes et le diagnostic. Escalader selon le contrôle obtenu et le retentissement.',steps('Confirmer la nature inflammatoire et rechercher les signes suspects.', 'Évaluer asthme, tolérance des anti-inflammatoires et symptômes du sommeil.', 'Instaurer soins locaux et traitement intranasal dans son indication.', 'Contrôler technique, observance, bénéfice et tolérance.', 'Si contrôle insuffisant, discuter chirurgie ou autre traitement spécialisé ; maintenir le suivi.')),
('La {prise en charge suisse débute souvent par soins locaux et corticostéroïde nasal}. Une chirurgie peut améliorer l’accès et la respiration. Elle ne supprime pas nécessairement la tendance inflammatoire.',paras('Les HUG et EPOS soutiennent les traitements locaux et les rinçages adaptés. Utiliser une solution prévue pour l’usage nasal et respecter l’hygiène du dispositif.', '@@MEDICAMENTS@@', 'Les antibiotiques ne sont pas un traitement de routine d’une polypose inflammatoire sans indication infectieuse. Les cures systémiques, traitements biologiques et gestes chirurgicaux relèvent du spécialiste selon sévérité, traitements déjà reçus et contre-indications ; aucun schéma empirique n’est ajouté ici.')),
('Le {suivi vérifie obstruction, odorat, sommeil et récidive}. Les soins locaux restent souvent nécessaires après chirurgie. Une évolution atypique doit être réexaminée.',paras('La notice Nasonex demande d’envisager un changement thérapeutique si la polypose ne s’améliore pas après cinq à six semaines. Une aggravation ou un signe d’alarme impose de revoir plus tôt.', 'Surveiller épistaxis, irritation et symptômes visuels sous corticoïde. Une respiration nasale améliorée ne justifie pas l’arrêt spontané d’une pression positive prescrite pour des apnées.')),
('Le {point clé est le contrôle d’une maladie inflammatoire chronique}. Polype ne signifie pas automatiquement cancer. L’aspect unilatéral atypique empêche toutefois une rassurance automatique.',paras('Les doses pour la polypose adulte sont différentes de celles de la rhinite allergique. Respecter l’âge autorisé et traiter les apnées associées pour elles-mêmes.'))]
quiz=[('Toute sinusite chronique comporte-t-elle des polypes ?','Non.'),('Quel trouble sensoriel est fréquent ?','Une diminution de l’odorat.'),('Une masse unilatérale sanglante doit-elle être explorée ?','Oui.'),('Un asthme associé doit-il être recherché ?','Oui.'),('Le scanner explique-t-il seul tous les symptômes ?','Non.'),('L’endoscopie aide-t-elle à caractériser les lésions ?','Oui.'),('Les antibiotiques sont-ils systématiques ?','Non.'),('Quel âge minimal concerne Nasonex pour les polypes dans la notice citée ?','Dix-huit ans.'),('La dose adulte initiale est-elle celle de la rhinite ?','Non : pour les polypes, deux pulvérisations par narine deux fois par jour dans la notice citée.'),('Quand la notice propose-t-elle de revoir la stratégie en l’absence d’amélioration ?','Après cinq à six semaines, plus tôt si aggravation ou alarme.'),('La chirurgie garantit-elle une guérison définitive ?','Non.'),('Les soins locaux peuvent-ils rester nécessaires après chirurgie ?','Oui.'),('La baisse du bruit prouve-t-elle la disparition des apnées ?','Non.'),('Un traitement biologique est-il indiqué pour chaque polype ?','Non, il nécessite une sélection spécialisée.')]
produire(6,parts,quiz,(1,4,8,12,18,22),lambda l:nasonex(l,True))
